  { builder: 'u_7311', seq: ['Gmail Trigger','AI Agent','Set','Google Sheets'] },
  { builder: 'u_8004', seq: ['Form','AI Agent','Switch','Airtable','Slack'] }
];
return [{ json: { builds: builds, window: 'last 30 days' } }];

const d = $input.first().json;
const counts = {};
d.builds.forEach(function (b) {
  for (let i = 0; i < b.seq.length - 2; i++) {
    for (let j = i + 3; j <= b.seq.length; j++) {
      const key = b.seq.slice(i, j).join(' -> ');
      if (!counts[key]) { counts[key] = { shape: key, length: j - i, builders: [] }; }
      if (counts[key].builders.indexOf(b.builder) === -1) { counts[key].builders.push(b.builder); }
    }
  }
});
const shapes = Object.keys(counts).map(function (k) { return counts[k]; })
  .filter(function (s) { return s.builders.length >= 3; })
  .sort(function (a, b) { return (b.builders.length * b.length) - (a.builders.length * a.length); })
  .slice(0, 5);
return [{ json: { candidate_shapes: shapes, total_builds: d.builds.length } }];

const d = $input.first().json;
const names = {
  'Webhook -> Set -> HTTP Request -> Code -> Slack': { name: 'Inbound Event to Enriched Alert', does: 'Takes an inbound webhook, normalises the payload, enriches it from an API, shapes the message and posts it to a channel.' },
  'Gmail Trigger -> AI Agent -> Set -> Google Sheets': { name: 'Inbox to Structured Row', does: 'Reads new mail, has a model pull structured fields out of it, and appends one clean row per message.' },
  'Form -> AI Agent -> Switch -> Airtable -> Slack': { name: 'Form Intake Triage', does: 'Classifies a form submission, routes it by category, records it and notifies the right owner.' }
};
const skills = d.candidate_shapes.map(function (s) {
  const meta = names[s.shape] || { name: 'Unnamed Pattern', does: 'Repeated shape with no card written yet.' };
  return {
    proposed_skill: meta.name,
    what_it_does: meta.does,
    shape: s.shape,
    rebuilt_by: s.builders.length,
    nodes_saved_each_time: s.length,
    total_nodes_never_to_be_wired_again: s.builders.length * s.length
  };
});
const top = skills[0] || null;
const say = top
  ? 'Nobody asked for a skill. ' + top.rebuilt_by + ' different builders independently wired the same ' + top.nodes_saved_each_time + '-node shape this month. That is not a coincidence, that is a missing primitive. Proposing it as the Skill \"' + top.proposed_skill + '\": ' + top.what_it_does
  : 'No shape was rebuilt by enough independent builders this window to justify a Skill.';
return [{ json: { plain_english: say, proposed_skills: skills, worth_shipping: skills.length > 0 } }];
